mapper.select:
select dtl.id as id, flow.flow_no as flowNo, flow.in_account_no as inAccountNo, flow.in_merchant_no as inMerchantNo, flow.in_account_type as inAccountType, flow.out_account_no as outAccountNo, flow.out_merchant_no as outMerchantNo, flow.out_account_type as out_account_type, flow.biz_type as bizType, flow.biz_order_no as bizOrderNo, flow.biz_order_date as bizOrderDate, flow.biz_order_time as bizOrderTime, flow.fee_type as feeType, flow.fee_amount as feeAmount, flow.remark as remark, dtl.flow_dtl_no as flowDtlNo, dtl.store_id as merchantNo, dtl.account_type as accountType, dtl.amount as amount, dtl.cur_balance as curBalance, dtl.fun_code as funCode, dtl.order_date as orderDate, dtl.fund_direction as fundDirection from t_set_account_flow as flow left join t_set_account_dtl as dtl on flow.flow_no = dtl.flow_no
and dtl.order_date between #{dto.startDate} and #{dto.endDate}
and (flow.in_account_no = #{dto.accountNo} or flow.out_account_no = #{dto.accountNo})
and (flow.in_account_type = #{dto.acctType} or flow.out_account_type = #{dto.acctType})
and dtl.fun_code = #{dto.funcode}
order by dtl.order_date desc, dtl.id desc
